css:
.btn-3d {
  position: relative;
  background: linear-gradient(145deg, #6e98e8, #3e65cd);
  border: none;
  border-radius: 12px;
  box-shadow:
    0 9px 15px rgba(62, 101, 205, 0.5),
    inset 0 5px 8px rgba(255, 255, 255, 0.3),
    inset 0 -5px 8px rgba(0, 0, 0, 0.3);
  color: white;
  padding: 18px 48px;
  font-size: 1.25rem;
  font-weight: 600;
  cursor: pointer;
  outline: none;
  transition:
    transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
    box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  user-select: none;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.25);
}

.btn-3d::before {
  content: "";
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  height: 14px;
  background: rgba(62, 101, 205, 0.5);
  border-radius: 0 0 12px 12px;
  filter: blur(8px);
  opacity: 0.5;
  transition: opacity 0.3s ease;
  pointer-events: none;
  transform-origin: top center;
}

.btn-3d:hover {
  transform: translateY(-6px);
  box-shadow:
    0 15px 25px rgba(62, 101, 205, 0.6),
    inset 0 5px 12px rgba(255, 255, 255, 0.4),
    inset 0 -6px 12px rgba(0, 0, 0, 0.4);
}

.btn-3d:hover::before {
  opacity: 0.75;
  filter: blur(12px);
  transform: scaleX(1.1) translateY(4px);
}

.btn-3d:active {
  transform: translateY(-2px);
  box-shadow:
    0 8px 12px rgba(62, 101, 205, 0.4),
    inset 0 3px 6px rgba(255, 255, 255, 0.3),
    inset 0 -3px 6px rgba(0, 0, 0, 0.3);
}
